const patterns = [
  { type: 'email', re: /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g },
  { type: 'iban', re: /\b[A-Z]{2}\d{2}(?:\s?[A-Z0-9]{4}){3,7}(?:\s?[A-Z0-9]{1,3})?\b/g },
  { type: 'card', re: /\b(?:\d[ -]?){12,18}\d\b/g },
  { type: 'phone', re: /(?:\+370|\b8)[\s-]?\(?\d{1,3}\)?[\s-]?\d{2,3}[\s-]?\d{2,5}\b/g },
  { type: 'personal_code', re: /\b[3-6]\d{10}\b/g },
];
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
return $input.all().map(item => {
  const j = item.json;
  const name = (j['Name'] || '').trim();
  let text = j['Message'] || '';
  const found = [];
  // Structured patterns first, so a name inside an email address can't break the email match.
  for (const p of patterns) {
    if (text.match(p.re)) { found.push(p.type); text = text.replace(p.re, `[${p.type.toUpperCase()}]`); }
  }
  for (const part of name.split(/\s+/).filter(p => p.length > 2)) {
    const re = new RegExp(`(?<!\\p{L})${esc(part)}(?!\\p{L})`, 'giu');
    if (re.test(text)) { found.push('name'); text = text.replace(re, '[NAME]'); }
  }
  return { json: {
    ticket_id: 'T-' + Date.now().toString(36).toUpperCase(),
    customer_name: name,
    customer_email: j['Email'] || '',
    order_number: j['Order number'] || '',
    message: j['Message'] || '',
    redacted_message: text,
    pii_found: found.length > 0,
    pii_types: [...new Set(found)],
  } };
});

// Deterministic check: a ticket that tries to instruct the model always goes to a person.
const INJECTION = [
  /ignore (all |any |your |the )?(previous |prior |above |earlier )?(instructions|rules|prompt)/i,
  /\b(system|developer) (prompt|message|override|instructions?)\b/i,
  /\b(classify|label|mark|tag|flag)\s+(this|the|my)(\s+(ticket|message|email|request))?\s+as\b/i,
  /\b(not|isn'?t) sensitive\b/i,
  /\bnote to the (ai|assistant|bot|model)\b/i,
  /\byou are (now )?(an? |the )?(ai|assistant|admin|bot|model)\b/i,
  /\b(never|do not|don'?t) escalate\b/i,
];
return $input.all().map((item, i) => {
  const ticket = $('Redact PII').all()[i].json;
  let labels;
  try { labels = JSON.parse(item.json.message.content); }
  catch (e) { labels = { category: 'other', urgency: 'high', sensitive: true, complexity: 'complex', requests: [], summary: 'Model output could not be parsed', parse_error: true }; }
  const injection_suspected = INJECTION.some(re => re.test(ticket.message || ''));
  if (injection_suspected) labels.sensitive = true;
  // Two or more separate requests make a ticket complex. Code only upgrades, never downgrades.
  if (Array.isArray(labels.requests) && labels.requests.length >= 2) labels.complexity = 'complex';
  return { json: { ...ticket, ...labels, injection_suspected, model: item.json.model, latency_s: Math.round((item.json.total_duration || 0) / 1e8) / 10 } };
});

// Join the retrieved help articles into one context field on the ticket
const ticket = $('Merge ticket').first().json;
const docs = $input.all().map(d => d.json);
const context = docs
  .map(d => `[${d.document?.metadata?.title ?? 'Article'}] ${d.document?.pageContent ?? ''}`)
  .join('\n\n');
const kb_titles = docs.map(d => d.document?.metadata?.title).filter(Boolean);
return [{ json: { ...ticket, context, kb_titles } }];

