const t = $('Add context').first().json;
const r = $input.first().json;
return [{ json: {
  ...t,
  route: 'local',
  draft: r.message?.content ?? '',
  draft_model: r.model,
  draft_latency_s: Math.round((r.total_duration || 0) / 1e8) / 10,
  status: 'pending_review',
}}];

const t = $('Add context').first().json;
const err = $input.first().json.error;
const reason = err
  ? 'PII guard blocked the cloud call: ' + String(typeof err === 'string' ? err : err.message).replace(/\s*\[line \d+\]/, '').replace(/^.*?:\s*/, '')
  : t.injection_suspected ? 'possible prompt injection'
  : t.sensitive ? 'sensitive ticket' : 'manual';
return [{ json: { ...t, route: 'human', draft: '', status: 'escalated', escalation_reason: reason } }];

// Fail closed: inspect exactly what will be sent to the cloud. If any personal data is found, stop.
const t = $input.first().json;
const cloud_prompt =
  'HELP ARTICLES:\n' + t.context +
  '\n\nCUSTOMER MESSAGE (personal data removed, order ' + (t.order_number || 'none') + '):\n' + t.redacted_message;

const checks = {
  email: /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/,
  phone: /(?:\+370|\b8)[\s-]?\(?\d{1,3}\)?[\s-]?\d{2,3}[\s-]?\d{2,5}\b/,
  card: /\b(?:\d[ -]?){12,18}\d\b/,
  personal_code: /\b[3-6]\d{10}\b/,
  iban: /\b[A-Z]{2}\d{2}(?:\s?[A-Z0-9]{4}){3,7}/,
};
const leaks = Object.keys(checks).filter(k => checks[k].test(cloud_prompt));

// Name check uses word stems, so inflected Lithuanian forms (Petrauskienės, Jonaičio) are caught too
const msg = (t.redacted_message || '').toLowerCase();
for (const part of (t.customer_name || '').split(/\s+/).filter(p => p.length > 2)) {
  const stem = part.toLowerCase().slice(0, Math.max(4, part.length - 3));
  if (msg.includes(stem)) leaks.push('name');
}
if (leaks.length) throw new Error('PII guard blocked the cloud call: ' + [...new Set(leaks)].join(', '));
return [{ json: { ...t, cloud_prompt } }];

const t = $('No-PII guard').first().json;
const firstName = (t.customer_name || '').split(/\s+/)[0] || '';
let draft = $input.first().json.text ?? '';
// Re-insert the customer's first name locally; the cloud model only saw [NAME]
if (firstName) draft = draft.replaceAll('[NAME]', firstName);
const { cloud_prompt, ...rest } = t;
return [{ json: { ...rest, route: 'cloud', draft, draft_model: 'cloud', status: 'pending_review' } }];

