const t = $('Queue item').first().json;
const f = $input.first().json;
const edited = (f['Final reply'] || '').trim();
let status, final_reply;
if (f['Decision'] === 'Approve') { status = t.draft ? 'approved' : 'needs_reply'; final_reply = t.draft; }
else if (f['Decision'] === 'Edit') { status = edited ? 'edited' : 'needs_reply'; final_reply = edited; }
else { status = 'rejected'; final_reply = ''; }
return [{ json: { ticket_id: t.ticket_id, status, final_reply, decision: f['Decision'] } }];
